def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

def daily_temperatures(temperatures):
    answer = [0] * len(temperatures)
    stack = []  # indices with temperatures waiting for a warmer day
    for i, temp in enumerate(temperatures):
        while stack and temperatures[stack[-1]] < temp:
            prev_index = stack.pop()
            answer[prev_index] = i - prev_index
        stack.append(i)
    return answer

def decode_string(s):
    stack = []
    curr_str = ''
    curr_num = 0

    for ch in s:
        if ch.isdigit():
            curr_num = curr_num * 10 + int(ch)
        elif ch == '[':
            stack.append((curr_str, curr_num))
            curr_str = ''
            curr_num = 0
        elif ch == ']':
            prev_str, num = stack.pop()
            curr_str = prev_str + curr_str * num
        else:
            curr_str += ch

    return curr_str

def calculate(s):
    stack = []
    num = 0
    sign = '+'
    s = s + '+'  # sentinel operator flushes the final number

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch in '+-*/':
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                prev = stack.pop()
                stack.append(int(prev / num))  # truncate toward zero
            sign = ch
            num = 0

    return sum(stack)
